#!/usr/bin/env swift
// Android TV for PS4 — GoldHEN FTP diagnostics (Baikal Pro boot investigation).
// Usage:
//   PS4_HOST=10.0.1.23 swift tools/ps4-android-tv-console.swift status
//   swift tools/ps4-android-tv-console.swift discover
//   swift tools/ps4-android-tv-console.swift pull [--out tmp/ps4-android-tv-logs]
import Foundation

struct Cfg {
    var host = ProcessInfo.processInfo.environment["PS4_HOST"] ?? "10.0.1.7"
    var port = 2121
    var repoRoot: URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
    }
    var logRoot = "/user/app/ps4-android"
}

@discardableResult
func curl(_ args: [String], timeout: Int = 30) -> (String, Int32) {
    let task = Process()
    task.executableURL = URL(fileURLWithPath: "/usr/bin/curl")
    task.arguments = ["-sS", "--connect-timeout", "5", "-m", "\(timeout)"] + args
    let out = Pipe()
    let err = Pipe()
    task.standardOutput = out
    task.standardError = err
    try? task.run()
    task.waitUntilExit()
    let s =
        (String(data: out.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? "")
            + (String(data: err.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? "")
    return (s, task.terminationStatus)
}

func discoverFTP() -> String? {
    let local = (try? sh("/sbin/ipconfig", ["getifaddr", "en0"])) ?? (try? sh("/sbin/ipconfig", ["getifaddr", "en1"])) ?? ""
    var hosts: [String] = ["10.0.1.7"]
    let parts = local.split(separator: ".")
    if parts.count == 4 {
        let base = parts.prefix(3).joined(separator: ".")
        for i in 1 ... 40 { hosts.append("\(base).\(i)") }
    }
    var seen = Set<String>()
    for h in hosts where seen.insert(h).inserted {
        if curl(["ftp://\(h):2121/"], timeout: 3).1 == 0 { return h }
    }
    return nil
}

func sh(_ bin: String, _ args: [String]) throws -> String {
    let task = Process()
    task.executableURL = URL(fileURLWithPath: bin)
    task.arguments = args
    let out = Pipe()
    task.standardOutput = out
    try task.run()
    task.waitUntilExit()
    return String(data: out.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8)?
        .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
}

func ftpList(_ host: String, _ path: String) -> String {
    curl(["ftp://\(host):2121/\(path)"], timeout: 15).0
}

func ftpSize(_ host: String, _ path: String) -> String {
    let (head, st) = curl(["-sSI", "ftp://\(host):2121/\(path)"], timeout: 15)
    guard st == 0 else { return "missing" }
    for line in head.split(separator: "\n") {
        if line.lowercased().hasPrefix("content-length:") {
            return String(line.split(separator: " ").last ?? Substring("?"))
        }
    }
    return "?"
}

func pull(_ cfg: Cfg, outDir: URL) throws {
    try FileManager.default.createDirectory(at: outDir, withIntermediateDirectories: true)
    let files = [
        "\(cfg.logRoot)/logs/launcher.log",
        "\(cfg.logRoot)/logs/launcher.previous.log",
        "\(cfg.logRoot)/logs/progress.log",
        "\(cfg.logRoot)/logs/kernel.log",
        "\(cfg.logRoot)/logs/hardware.txt",
        "\(cfg.logRoot)/boot/bzImage-baikal",
        "\(cfg.logRoot)/boot/bootargs.txt",
        "\(cfg.logRoot)/boot/vram.txt",
    ]
    for remote in files {
        let local = outDir.appendingPathComponent(remote.replacingOccurrences(of: "/", with: "_"))
        let (_, st) = curl(["-o", local.path, "ftp://\(cfg.host):\(cfg.port)/\(remote)"], timeout: 600)
        let tag = st == 0 ? "OK" : "skip"
        print("\(tag) \(remote)")
    }
    print("Saved under \(outDir.path)")
}

func analyzeLauncher(_ text: String) {
    let lines = text.split(separator: "\n").map(String.init)
    print("--- launcher.log summary ---")
    for key in ["southbridge=", "stage=7", "handed over", "bytes=", "errno="] {
        for line in lines where line.contains(key) { print(line) }
    }
    let linuxLogs = ["progress.log", "kernel.log", "hardware.txt"]
    print("Linux-side logs on console: check pull output (missing = never reached initramfs logging).")
    _ = linuxLogs
}

let args = Array(CommandLine.arguments.dropFirst())
var cfg = Cfg()
if let i = args.firstIndex(of: "--host"), i + 1 < args.count { cfg.host = args[i + 1] }

guard let cmd = args.first(where: { $0 != "--host" && !$0.hasPrefix("--") && $0 != cfg.host }) ?? args.first else {
    print("""
    Android TV console tool
      discover — find GoldHEN FTP on LAN
      status   — boot files + launcher summary
      pull     — download logs + boot assets to tmp/
    Env: PS4_HOST (default 10.0.1.7)
    """)
    exit(0)
}

switch cmd {
case "discover":
    if let h = discoverFTP() {
        print("FTP: ftp://\(h):2121/")
        print("export PS4_HOST=\(h)")
    } else {
        print("No GoldHEN FTP on LAN (port 2121)")
        exit(1)
    }
case "status":
    if curl(["ftp://\(cfg.host):\(cfg.port)/"], timeout: 5).1 != 0 {
        if let found = discoverFTP() {
            print("Note: \(cfg.host) down; using discovered \(found)")
            cfg.host = found
        } else {
            print("\(cfg.host): offline")
            exit(1)
        }
    }
    print("=== Android TV @ \(cfg.host) ===")
  let boot = [
        ("bzImage-baikal", "\(cfg.logRoot)/boot/bzImage-baikal"),
        ("initramfs", "\(cfg.logRoot)/boot/initramfs.cpio.xz"),
        ("linux.elf payload (in PKG only)", "—"),
    ]
    for (label, path) in boot {
        let sz = path == "—" ? "960689 B embedded in app" : ftpSize(cfg.host, path)
        print("  \(label): \(sz) bytes")
    }
    let (launch, st) = curl(["ftp://\(cfg.host):\(cfg.port)/\(cfg.logRoot)/logs/launcher.log"], timeout: 30)
    if st == 0, !launch.isEmpty { analyzeLauncher(launch) } else { print("launcher.log: missing") }
    for name in ["progress.log", "kernel.log", "hardware.txt"] {
        let p = "\(cfg.logRoot)/logs/\(name)"
        print("  \(name): \(ftpSize(cfg.host, p))")
    }
case "pull":
    var out = cfg.repoRoot.appendingPathComponent("tmp/ps4-android-tv-logs", isDirectory: true)
    if let i = args.firstIndex(of: "--out"), i + 1 < args.count {
        out = URL(fileURLWithPath: args[i + 1], isDirectory: true)
    }
    if curl(["ftp://\(cfg.host):\(cfg.port)/"], timeout: 5).1 != 0, let found = discoverFTP() {
        cfg.host = found
    }
    try pull(cfg, outDir: out)
default:
    print("Unknown: \(cmd)")
    exit(1)
}

