#!/usr/bin/env bash
# Run Baikal bzImage build in amd64 Docker (macOS-safe).
# Kernel source is reused from build/android-tv-kernel/deps/crashniels-linux (not re-cloned each run).

atv_kernel_tree_paths() {
	local root="${1:?repo root}"
	ATV_REPO_ROOT="${root}"
	ARTIFACT_ROOT="${root}/build/android-tv-kernel"
	DEPS="${ARTIFACT_ROOT}/deps/crashniels-linux"
