"""Kexec build cache, firmware defines, and confirmed-hash policy."""
from __future__ import annotations

import hashlib
import json
import os
import re
from pathlib import Path


def loader_source_fingerprint(loader_root: Path) -> dict[str, str]:
    return {
        str(p.relative_to(loader_root)): hashlib.sha256(p.read_bytes()).hexdigest()
        for p in sorted(loader_root.rglob("*"))
        if p.is_file()
    }


def parse_magic_defines(magic_h_text: str) -> list[str]:
    defines = re.findall(
        r"^#(?:if|elif) defined\s+(PS4_\d+_\d+)|^#ifdef\s+(PS4_\d+_\d+)",
        magic_h_text,
        re.M,
    )
    names = [a or b for a, b in defines]
    if len(names) != len(set(names)):
        raise ValueError("duplicate firmware defines in magic.h")
    return names


def fw_code_from_define(define: str) -> int:
    major, minor = define.split("_")[1:]
    return int(major) * 100 + int(minor)


def try_kexec_cache(
    out_dir: Path,
    loader_root: Path,
    *,
    env: dict[str, str] | None = None,
) -> bool:
    env = env if env is not None else os.environ
    stamp = out_dir / "kexec-build.json"
    header = out_dir / "kexec-images.h"
    if env.get("ATV_KEXEC_FORCE") == "1":
        return False
    if not stamp.is_file() or not header.is_file():
        return False
    try:
        old = json.loads(stamp.read_text())
    except json.JSONDecodeError:
        return False
    if old.get("source_sha256") != loader_source_fingerprint(loader_root):
        return False
    return True


def kexec_confirmed_check(
    fw: int,
    blob: bytes,
    confirmed: dict[int, str],
    *,
    env: dict[str, str] | None = None,
) -> None:
    """Raise AssertionError on strict mismatch; otherwise caller may log warnings."""
    env = env if env is not None else os.environ
    if fw not in confirmed:
        return
    got = hashlib.sha256(blob).hexdigest()
    pinned = confirmed[fw]
    if got == pinned:
        return
    strict = (
        env.get("ATV_KEXEC_STRICT_CONFIRMED") == "1"
        and env.get("ATV_KEXEC_RELAX_CONFIRMED") != "1"
    )
    if strict:
        raise AssertionError(fw)
    # Non-strict: no exception (build-kexec prints WARNING)


def per_fw_cache_hit(
    directory: Path,
    src_sig: str,
    *,
    env: dict[str, str] | None = None,
) -> bool:
    env = env if env is not None else os.environ
    marker = directory / ".source_stamp"
    bin_out = directory / "kexec.bin"
    if env.get("ATV_KEXEC_FORCE_FW"):
        return False
    if not marker.is_file() or not bin_out.is_file():
        return False
    return marker.read_text() == src_sig


def build_kexec_manifest(
    images: list[tuple[int, bytes]],
    loader_root: Path,
    upstream_lines: list[str],
    confirmed: dict[int, str],
) -> dict:
    return {
        "upstream": upstream_lines,
        "images": {
            str(fw): {
                "bytes": len(blob),
                "sha256": hashlib.sha256(blob).hexdigest(),
                "console_confirmed": fw in confirmed,
            }
            for fw, blob in images
        },
        "source_sha256": loader_source_fingerprint(loader_root),
    }


def render_kexec_images_h(images: list[tuple[int, bytes]]) -> str:
    data = b"".join(blob for _, blob in images)
    rows = [",".join("0x%02x" % b for b in data[i : i + 16]) for i in range(0, len(data), 16)]
    table = []
    offset = 0
    for fw, blob in images:
        table.append("{%d,%d,%d}" % (fw, offset, len(blob)))
        offset += len(blob)
    return (
        "struct atv_kexec_image{unsigned short firmware;unsigned int offset,bytes;};\n"
        "#define ATV_KEXEC_MAX_BYTES %d\n" % max(len(b) for _, b in images)
        + "static const struct atv_kexec_image atv_kexec_images[]={"
        + ",".join(table)
        + "};\n"
        + "static const unsigned char atv_kexec_data[]={\n"
        + ",\n".join(rows)
        + "\n};\n"
    )

"""Boot payload kexec pin verification."""
from __future__ import annotations

import hashlib
from pathlib import Path


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def resolve_kexec_expected(
    actual: str,
    expected: str,
    *,
    relax: bool,
) -> str:
    if actual == expected:
        return expected
    if relax:
        return actual
    raise AssertionError("Do not substitute the failed native handoff loader")

"""Split unified git patches into per-file slices."""
from __future__ import annotations

import re
from pathlib import Path


def safe_name(path: str) -> str:
    return path.replace("/", "__")


def split_unified_patch(text: str) -> dict[str, str]:
    chunks = re.split(r"(?=^diff --git )", text, flags=re.M)
    out: dict[str, str] = {}
    for chunk in chunks:
        chunk = chunk.strip()
        if not chunk.startswith("diff --git"):
            continue
        match = re.search(r"^diff --git a/(.+?) b/", chunk, re.M)
        if not match:
            continue
        relpath = match.group(1)
        out[relpath] = chunk + "\n"
    return out


def write_patch_slices(text: str, outdir: Path) -> int:
    outdir.mkdir(parents=True, exist_ok=True)
    slices = split_unified_patch(text)
    for relpath, body in slices.items():
        (outdir / f"{safe_name(relpath)}.patch").write_text(body)
    return len(slices)

