def _deps_git_head(deps_git: Path) -> str:
  """Best-effort HEAD; never block on a broken or recursive git wrapper."""
  if not deps_git.is_dir():
    return "no-head"
  git_marker = deps_git / ".git"
  if not git_marker.exists():
    return "no-head"
  try:
    head = subprocess.run(
      ["git", "-C", str(deps_git), "rev-parse", "HEAD"],
      capture_output=True,
      text=True,
      check=False,
      timeout=3,
    )
  except (subprocess.TimeoutExpired, OSError):
    return "no-head"
  return head.stdout.strip() if head.returncode == 0 else "no-head"


